"""Core routines.

A set is a sorted tuple A = (0, a_1, ..., d) of integers with gcd 1. Its homogenized
semigroup S is generated by the points (a, d - a); a point (x, y) of S has level (x + y)/d,
and x lies in the h-fold sumset hA exactly when (x, hd - x) lies in S.

All routines are exact (Python integers used as bitsets) and deterministic.
"""
from math import gcd


def set_gcd(values):
    g = 0
    for v in values:
        g = gcd(g, v)
    return g


def conductor(gens):
    """Conductor of the numerical semigroup generated by gens (gcd 1): its largest gap plus one."""
    gens = [g for g in gens if g > 0]
    limit = max(gens) ** 2 + 2
    mask = (1 << (limit + 1)) - 1
    reach = 1
    while True:
        nxt = reach
        for g in gens:
            nxt |= (reach << g) & mask
        if nxt == reach:
            break
        reach = nxt
    return (~reach & mask).bit_length()


def semigroup_members(gens, limit):
    """Bitset of the elements of <gens> in [0, limit]."""
    gens = [g for g in gens if g > 0]
    mask = (1 << (limit + 1)) - 1
    reach = 1
    while True:
        nxt = reach
        for g in gens:
            nxt |= (reach << g) & mask
        if nxt == reach:
            return reach
        reach = nxt


def bits(x):
    """Positions of the set bits of x, in increasing order."""
    out = []
    while x:
        low = x & -x
        out.append(low.bit_length() - 1)
        x ^= low
    return out


def apery_points(A):
    """The homogenized Apery set {s in S : s - (0, d) and s - (d, 0) are not in S}, as a sorted
    list of points (x, y). Its levels are contiguous from 0, so the search stops at the first
    level without Apery points."""
    d = A[-1]
    prev = 1          # 0A0 = {0}
    pts = [(0, 0)]
    s = 0
    while True:
        s += 1
        cur = 0
        for a in A:
            cur |= prev << a
        ap = cur & ~(prev | (prev << d))
        if not ap:
            break
        for x in bits(ap):
            pts.append((x, s * d - x))
        prev = cur
    return sorted(pts)


def invariants(A):
    """Invariants of the curve of A from its homogenized Apery set.

    Returns a dict with d, acm, mAP (largest Apery level), tau (least level from which every
    sumset equals its intersection form; 0 if none fails), reg = max(tau, mAP), the numerical
    Apery maxima M1, M2 with respect to d, the conductors c1, c2, N = ceil((c1 + c2)/d), and
    for ACM sets the defect E = M1 + M2 - reg*d.

    In each residue class of the first coordinate modulo d the Apery points form a staircase
    (x_0, y_0), ..., (x_k, y_k) with x increasing and y decreasing; the failing points of the
    class are the lattice points dominated by none of them, and the largest level among them is
    (x_{j+1} + y_j)/d - 2 over consecutive pairs. The least x and the least y in each class are
    the numerical Apery elements of S1 and S2.
    """
    d = A[-1]
    pts = apery_points(A)
    classes = {}
    for x, y in pts:
        classes.setdefault(x % d, []).append((x, y))
    M1 = max(min(p[0] for p in c) for c in classes.values())
    M2 = max(min(p[1] for p in c) for c in classes.values())
    top = None
    for c in classes.values():
        c.sort()
        for j in range(len(c) - 1):
            v = c[j + 1][0] + c[j][1]
            if top is None or v > top:
                top = v
    acm = len(pts) == d
    tau = 0 if top is None else (top - 2 * d) // d + 1
    mAP = max((x + y) // d for x, y in pts)
    reg = max(tau, mAP)
    c1 = M1 - d + 1
    c2 = M2 - d + 1
    N = -(-(c1 + c2) // d)
    out = dict(d=d, acm=acm, mAP=mAP, tau=tau, reg=reg, M1=M1, M2=M2, c1=c1, c2=c2, N=N)
    if acm:
        out["E"] = M1 + M2 - reg * d
    return out


def reflect(A):
    d = A[-1]
    return tuple(sorted(d - a for a in A))


def brute_invariants(A, hmax=None):
    """tau, c1, c2 by direct sumsets: compares hA with the intersection form
    {x in [0, hd] : x in S1, hd - x in S2} for h = 1, ..., hmax (default 3d)."""
    d = A[-1]
    hmax = hmax or 3 * d
    lim = hmax * d
    s1 = semigroup_members(A[1:], lim)
    s2 = semigroup_members([d - a for a in A[:-1]], lim)
    c1 = conductor(A[1:])
    c2 = conductor([d - a for a in A[:-1]])
    cur = 1
    fails = []
    for h in range(1, hmax + 1):
        nxt = 0
        for a in A:
            nxt |= cur << a
        cur = nxt
        hd = h * d
        # bit x of form is set when x in S1 and hd - x in S2
        mask = (1 << (hd + 1)) - 1
        s1h = s1 & mask
        s2h = s2 & mask
        s2_reflected = int(format(s2h, "0%db" % (hd + 1))[::-1], 2) if s2h else 0
        form = s1h & s2_reflected
        if form != cur:
            fails.append(h)
    tau = fails[-1] + 1 if fails else 0
    return dict(d=d, tau=tau, c1=c1, c2=c2, fails=fails)
